    lo = 0
    hi = len(arr)

    while lo <= hi:
        mid = (lo + hi) // 2

        if x == arr[mid] and (mid == 0 or x != arr[mid - 1]):
            return mid
        if x <= arr[mid]:
            hi = mid
        else:
            lo = mid + 1

